package ru.homebooks.library;

import android.app.*;
import android.graphics.Color;
import android.graphics.drawable.ColorDrawable;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;

final class BookSeriesUi {
    interface Chosen {void apply(BookSeries series);}
    static void choose(Activity activity,Long selected,Chosen chosen,Runnable create){LibraryApp app=(LibraryApp)activity.getApplication();app.io.execute(()->{try{List<BookSeries> items=app.store.bookSeries();activity.runOnUiThread(()->{if(!activity.isDestroyed()&&!activity.isFinishing())show(activity,items,selected,chosen,create);});}catch(Exception e){activity.runOnUiThread(()->Toast.makeText(activity,"Не удалось загрузить серии",Toast.LENGTH_LONG).show());}});}
    private static void show(Activity activity,List<BookSeries> items,Long selected,Chosen chosen,Runnable create){
        Dialog dialog=new Dialog(activity);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout panel=Ui.column(activity);panel.setPadding(Ui.dp(activity,20),Ui.dp(activity,16),Ui.dp(activity,20),Ui.dp(activity,24));panel.setBackground(Ui.surface(activity,Color.WHITE,Color.WHITE,22));dialog.setContentView(panel);dialog.setCanceledOnTouchOutside(true);
        TextView title=Ui.heading(activity,"Серия или журнал");panel.addView(title);Ui.gap(panel,12);EditText search=Ui.search(activity,"Найти по названию");panel.addView(search);Ui.gap(panel,8);List<BookSeries> all=new ArrayList<>(),visible=new ArrayList<>();all.add(new BookSeries(-1,"Без серии",BookSeries.BOOKS,null,Collections.emptyList()));all.addAll(items);visible.addAll(all);final Long[] pending={selected};
        ListView list=new ListView(activity);list.setDivider(new ColorDrawable(Ui.LINE));list.setDividerHeight(Ui.dp(activity,1));BaseAdapter adapter=new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int p){return visible.get(p);}public long getItemId(int p){return visible.get(p).id;}public View getView(int p,View reuse,ViewGroup parent){BookSeries item=visible.get(p);LinearLayout row=new LinearLayout(activity);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,Ui.dp(activity,8),0,Ui.dp(activity,8));row.setMinimumHeight(Ui.dp(activity,60));ImageView icon=new ImageView(activity);icon.setImageDrawable(new Ui.Symbol(item.id<0?"tag":item.icon(),item.id<0?Ui.MUTED:Ui.GREEN));row.addView(icon,new LinearLayout.LayoutParams(Ui.dp(activity,34),Ui.dp(activity,34)));LinearLayout words=Ui.column(activity);words.setPadding(Ui.dp(activity,12),0,0,0);words.addView(Ui.text(activity,item.name,15));if(item.id>=0)words.addView(Ui.muted(activity,item.kindLabel()+" · "+item.members.size(),12));row.addView(words,new LinearLayout.LayoutParams(0,-2,1));RadioButton radio=new RadioButton(activity);radio.setClickable(false);radio.setChecked(item.id<0?pending[0]==null:pending[0]!=null&&pending[0]==item.id);radio.setButtonTintList(android.content.res.ColorStateList.valueOf(Ui.GREEN));row.addView(radio);return row;}};
        list.setAdapter(adapter);panel.addView(list,new LinearLayout.LayoutParams(-1,Math.min(Ui.dp(activity,330),activity.getResources().getDisplayMetrics().heightPixels/3)));Ui.gap(panel,10);Button add=Ui.quietAction(activity,"Новая серия или журнал","library",()->{dialog.dismiss();create.run();});panel.addView(add);Ui.gap(panel,8);LinearLayout actions=new LinearLayout(activity);Button cancel=Ui.quietAction(activity,"Отмена",dialog::dismiss);Button save=Ui.primary(activity,"Готово",()->{BookSeries result=null;if(pending[0]!=null)for(BookSeries item:items)if(item.id==pending[0])result=item;dialog.dismiss();chosen.apply(result);});actions.addView(cancel,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,-2,1);sp.setMarginStart(Ui.dp(activity,8));actions.addView(save,sp);panel.addView(actions);
        list.setOnItemClickListener((parent,view,index,id)->{BookSeries item=visible.get(index);pending[0]=item.id<0?null:item.id;adapter.notifyDataSetChanged();});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){String q=s.toString().trim().toLowerCase(Locale.ROOT);visible.clear();for(BookSeries item:all)if(item.name.toLowerCase(Locale.ROOT).contains(q))visible.add(item);adapter.notifyDataSetChanged();}});
        dialog.show();Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams params=window.getAttributes();params.gravity=Gravity.BOTTOM;params.width=-1;params.height=-2;params.dimAmount=.32f;window.setAttributes(params);window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);}
    }
}
